+/* Diagnostic only: bytes currently eligible for a non-spill flush.
+ * Includes overflow runs; excludes loose/kept pages just as page_flush does.
+ * Only observed between synchronous calls in this workload's small RW txns.
+ */
+size_t wok_lab_dirty_bytes(MDB_txn *txn) {
+    MDB_ID2L dl = txn->mt_u.dirty_list;
+    size_t pages = 0;
+    unsigned i;
+    for (i = 1; i <= dl[0].mid; ++i) {
+        MDB_page *p = dl[i].mptr;
+        if (!(p->mp_flags & (P_LOOSE|P_KEEP)))
+            pages += IS_OVERFLOW(p) ? p->mp_pages : 1;
+    }
+    return pages * txn->mt_env->me_psize;
+}
